import{_ as r,C as a,o as s,c as i,E as t,a2 as d}from"./chunks/framework.Bx6eOp9J.js";const h="/joinwell52/assets/handoff-boundaries-20261105/handoff-inheritance-mobile.en.svg",c="/joinwell52/assets/handoff-boundaries-20261105/handoff-inheritance.en.svg",b=JSON.parse(`{"title":"When another AI takes over, what should travel with the task?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"When another AI takes over, what should travel with the task?","date":"2026-11-05","published_date":"2026-11-05","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Can data, a workspace, an old decision and a memory follow the same inheritance rule when an agent takes over?","summary":"We exercised four narrow open-source paths and compared them with CodeFlowMu's task, review and authorization checks. Each thing carried across a handoff needs its own evidence.","cover":"/assets/handoff-boundaries-20261105/handoff-inheritance.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Four pinned component probes, six CodeFlowMu focused test files and one contract probe; no complete cross-product workflow or paid cloud distillation","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-05-what-an-agent-inherits.md","filePath":"en/research/2026-11-05-what-an-agent-inherits.md","lastUpdated":1793864474000}`),l={name:"en/research/2026-11-05-what-an-agent-inherits.md"},p=h;function u(g,e,m,w,f,v){const o=a("ArticleCover"),n=a("ArticleTableScroll");return s(),i("div",null,[t(o,{image:"/assets/handoff-boundaries-20261105/handoff-inheritance.cover-v1.png",kicker:"Engineering research · Agent handoffs",title:"When another AI takes over, what should travel with the task?",summary:"We exercised four narrow open-source paths and compared them with CodeFlowMu's task, review and authorization checks. Each thing carried across a handoff needs its own evidence.",version:"2026-11-05",languageHref:"/zh/research/2026-11-05-what-an-agent-inherits",languageLabel:"中文"}),t(n,{language:"en"}),e[0]||(e[0]=d('<h1 id="when-another-ai-takes-over-what-should-travel-with-the-task" tabindex="-1">When another AI takes over, what should travel with the task? <a class="header-anchor" href="#when-another-ai-takes-over-what-should-travel-with-the-task" aria-label="Permalink to &quot;When another AI takes over, what should travel with the task?&quot;">​</a></h1><p>Imagine a development agent passing a task to a testing agent. The tester opens the same project folder, sees the previous agent&#39;s notes and report, and can even find the earlier conversation. An obvious question follows: <strong>does the earlier approval travel with them too?</strong></p><p>Assigning a new worker changes who is responsible. Task data, the workspace, a pending human decision, and experience that may later become memory each have different origins and conditions of use. We are building CodeFlowMu, a local multi-agent work system that uses FCoP for formal tasks, reports and reviews. In our <a href="https://joinwell52-ai.github.io/joinwell52/en/runtime/daily-intelligence/2026-11-05" target="_blank" rel="noreferrer">daily two-layer research review</a>, changes in AG2, LangGraph, Paradev and Anthropic&#39;s cookbook pointed at the same engineering question from four directions: <strong>what actually survives a handoff?</strong></p><p>We pinned versions, exercised four narrow code paths, then checked CodeFlowMu&#39;s existing implementation and tests. These were separate boundary experiments, not one production team built from four frameworks. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-05-handoff-boundaries/00-report.en.md" target="_blank" rel="noreferrer">public evidence and rerunnable probes</a> include inputs, outputs and limits.</p><h2 id="first-the-task-data" tabindex="-1">First: the task data <a class="header-anchor" href="#first-the-task-data" aria-label="Permalink to &quot;First: the task data&quot;">​</a></h2><p><a href="https://github.com/ag2ai/ag2/releases/tag/v1.3.0" target="_blank" rel="noreferrer">AG2 1.3</a> lets a delegated variable stay local, be copied to a child, or be shared. We placed one of each in a parent scope, derived two child scopes, and changed values from one child. The local value was absent from the child. After the child changed the copied value to <code>1</code>, the parent and sibling still held <code>0</code>. After it changed the shared value to <code>1</code>, all three saw <code>1</code>. The child could not declare a new shared key.</p><p>That is an answer about <strong>data movement</strong>, not permission to act. The scope API also does not synchronize concurrent writes for an application. We did not run a model-driven parent-child conversation, so this probe cannot validate AG2&#39;s entire delegation flow.</p><h2 id="second-an-answer-to-an-earlier-question" tabindex="-1">Second: an answer to an earlier question <a class="header-anchor" href="#second-an-answer-to-an-earlier-question" aria-label="Permalink to &quot;Second: an answer to an earlier question&quot;">​</a></h2><p>In a local checkpoint graph using <a href="https://github.com/langchain-ai/langgraph/releases/tag/1.2.20" target="_blank" rel="noreferrer">LangGraph 1.2.20</a>, we placed two human questions in sequence: approve the plan, then approve the execution. The first question received one ID; after its answer, the second received a different ID. We deliberately submitted a nonexistent ID, the first question&#39;s consumed ID, and the second question&#39;s ID after completion. All three were rejected. Only two answers addressed to the current questions produced a final result.</p><p>This probe enabled the version&#39;s internal strict-resume setting and used an in-memory checkpointer. It shows that <strong>an answer can be tied to the pending question</strong>. It does not establish the default behavior of a remote deployment. Enterprise approval also needs the approver, target, action, deadline and actual executor checked.</p><h2 id="third-the-workspace-and-the-conversation" tabindex="-1">Third: the workspace and the conversation <a class="header-anchor" href="#third-the-workspace-and-the-conversation" aria-label="Permalink to &quot;Third: the workspace and the conversation&quot;">​</a></h2><p>The automation target planner in <a href="https://github.com/ParadevAI/Paradev/releases/tag/desktop-v2.0.5" target="_blank" rel="noreferrer">Paradev 2.0.5</a> treats workspace reuse and agent-session continuation as separate choices. We ran its original planner from a pinned Git object. Reusing a workspace while starting a fresh agent session is a valid combination. Requesting continuation without a pinned workspace turns reuse on. One less obvious result: when an existing target already reuses its workspace, changing hosts leaves reuse and continuation enabled in the plan while listing the new host for verification.</p><p>That is <strong>planner output</strong>. This release has no Windows desktop asset; we did not run its desktop app or cloud dispatch. Nor did we verify that the new host was accepted or that an old authorization remained valid. An enterprise system must answer three separate questions: where are the files, can the conversation continue, and may this actor still execute?</p><figure><picture><source media="(max-width: 640px)" srcset="'+p+'"><img src="'+c+'" alt="A task handoff checks data scope, current authority and delivery evidence separately; workspace reuse alone does not change approval state"></picture><figcaption>A synthesis of the research questions, with each checkpoint grounded in a probe or a CodeFlowMu test. This is not a newly deployed workflow.</figcaption></figure><h2 id="only-then-what-becomes-lasting-experience" tabindex="-1">Only then: what becomes lasting experience? <a class="header-anchor" href="#only-then-what-becomes-lasting-experience" aria-label="Permalink to &quot;Only then: what becomes lasting experience?&quot;">​</a></h2><p>Anthropic&#39;s <a href="https://github.com/anthropics/claude-cookbooks/pull/959" target="_blank" rel="noreferrer">dreaming cookbook</a> explores distilling completed sessions into longer-lived memory. We ran its official helper module over 11 transcripts provided in the repository. Empty input, a zero budget, and a file count above the limit were rejected before distillation. A still-running analyzer thread did not count as completed input coverage. The estimated list price was about $0.70; it was an estimate, not a model bill.</p><p>We did not invoke paid Managed Agents or generate a memory store. The local result still exposes a useful boundary: <strong>preserving old content and promoting it to organizational experience are separate decisions.</strong> A failed task, an unreviewed report or a record without a clear source needs to keep that status when summarized.</p><h2 id="back-to-our-own-agent-team" tabindex="-1">Back to our own agent team <a class="header-anchor" href="#back-to-our-own-agent-team" aria-label="Permalink to &quot;Back to our own agent team&quot;">​</a></h2><p>CodeFlowMu hands work among PM, development, QA and operations roles. At a pinned commit we ran six focused test suites: 77 tests passed. The informative results are narrower than the total. A worker report marked <code>done</code> does not itself become the PM&#39;s review decision. A downstream task requiring upstream success does not start merely because a report exists. Commands from stale task rounds or revisions are rejected. Technical automation requires a scoped grant. In a separate direct probe of the real session-contract functions, changing the host, workspace, role or allowed governance tools produced a corresponding conflict field.</p><p>One older end-to-end fixture stopped at Python output parsing on this machine. It is excluded from the 77 passes and was not used to infer a product defect; the evidence page records its failure point and scope.</p><p>These existing boundaries address <strong>who may decide and which facts can move work forward</strong>. They do not prove that a real UI, model conversation, host takeover and external tool effect remain consistent through one complete handoff. We therefore did not turn the upstream approaches into a CodeFlowMu defect claim or development ticket.</p><p>The next experiment is concrete: take one task through <strong>PM assignment → worker report → reviewer takeover</strong>. Change the workspace or host in between, revoke an approval, replay an old answer, and observe data, current authority and delivery evidence at each step. A contradiction along that path would give us a reason to consider a change.</p><p>For builders, one immediate check is: <strong>what does your “continue task” action actually restore: files, conversation, pending work, or execution authority?</strong> For people using these teams, which experience should the next AI retain, and which decision should it ask you to make again?</p>',23))])}const y=r(l,[["render",u]]);export{b as __pageData,y as default};
